#include "lib.h"

#include <stdio.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdlib.h>
#include <inttypes.h>

static uint32_t rng_state = 0x13572468u;

static uint32_t xorshift32(void) {
    uint32_t x = rng_state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    rng_state = x;
    return x;
}

static float rand_range(float lo, float hi) {
    uint32_t r = xorshift32();
    float u = (float)(r >> 8) / (float)(1u << 24); /* [0,1) */
    return lo + u * (hi - lo);
}

static int g_case_id = 1;

static void run_case(float h, float s, float v) {
    float src[3];
    float dest[3];
    src[0] = h;
    src[1] = s;
    src[2] = v;
    dest[0] = 0.0f;
    dest[1] = 0.0f;
    dest[2] = 0.0f;
    hsv_to_rgb(dest, src);
    printf("case %d h=%a s=%a v=%a r=%a g=%a b=%a\n", g_case_id, (double)h,
           (double)s, (double)v, (double)dest[0], (double)dest[1],
           (double)dest[2]);
    g_case_id++;
}

int main(void) {
    static const float hues[] = {
        0.0f,    10.0f,   59.9f,   60.0f,   60.1f,   90.0f,   119.9f,
        120.0f,  120.1f,  150.0f,  179.9f,  180.0f,  180.1f,  210.0f,
        239.9f,  240.0f,  240.1f,  270.0f,  299.9f,  300.0f,  300.1f,
        330.0f,  359.9f,  360.0f,  360.1f,  400.0f,  720.0f,  -0.1f,
        -1.0f,   -10.0f,  -59.0f,  -60.0f,  -61.0f,  -119.0f, -120.0f,
        -200.0f, -300.0f, -360.0f, -400.0f, -720.0f};
    size_t n = sizeof(hues) / sizeof(hues[0]);
    size_t hi;
    int i;

    /* s == 0 short-circuits to (v, v, v) regardless of h. */
    run_case(0.0f, 0.0f, 0.0f);
    run_case(123.0f, 0.0f, 0.5f);
    run_case(-45.0f, 0.0f, 1.0f);
    run_case(400.0f, 0.0f, -0.3f);
    run_case(10.0f, 0.0f, 2.0f);

    /* Sweep every branch of the i = floor(h/60) switch (cases 0..4 and
       the default, which also covers i == 5, negative i, and i >= 6),
       including hue values right at and straddling each boundary and
       outside [0, 360). */
    for (hi = 0; hi < n; ++hi) {
        run_case(hues[hi], 0.5f, 0.5f);
    }

    /* Extreme / out-of-range saturation and value inputs. */
    run_case(30.0f, 1.0f, 0.0f);
    run_case(90.0f, 1.0f, 1.0f);
    run_case(150.0f, 1.0f, 0.5f);
    run_case(210.0f, -0.5f, 0.5f);
    run_case(270.0f, 2.0f, 0.5f);
    run_case(330.0f, 0.5f, -1.0f);
    run_case(45.0f, 0.5f, 2.0f);

    for (i = 0; i < 30; ++i) {
        float h = rand_range(-720.0f, 720.0f);
        float s = rand_range(-1.0f, 2.0f);
        float v = rand_range(-1.0f, 2.0f);
        run_case(h, s, v);
    }

    return 0;
}
